import{_ as l,r as t,o as i,c as r,e,a,s as p,d as s}from"./chunks/framework.CXcwiNg-.js";const q=JSON.parse('{"title":"介绍 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"链接到媒体","slug":"链接到媒体","link":"#链接到媒体","children":[]},{"level":2,"title":"配置选项","slug":"配置选项","link":"#配置选项","children":[{"level":4,"title":"SVG 上传默认禁用","slug":"svg-上传默认禁用","link":"#svg-上传默认禁用","children":[]}]},{"level":2,"title":"音频和视频播放器","slug":"音频和视频播放器","link":"#音频和视频播放器","children":[]},{"level":2,"title":"事件","slug":"事件","link":"#事件","children":[]}],"relativePath":"2.x/zh-cn/media/introduction.md","filePath":"2.x/zh-cn/media/introduction.md"}'),u={name:"2.x/zh-cn/media/introduction.md"};function d(g,n,k,h,m,v){const o=t("pre-heading"),c=t("post-heading");return i(),r("div",null,[e(o),n[0]||(n[0]=a("h1",null,"介绍",-1)),e(c),n[1]||(n[1]=p(`<p>October CMS 附带了一个内置的媒体管理器，可以轻松发布更多的资产，例如视频和照片。然后可以通过用户界面将这些资产插入到您的页面和内容文件中。</p><p><img src="https://i.ibb.co/wNfs7KK/media-manager.png" alt="image"></p><h2 id="链接到媒体"><a href="#链接到媒体" class="header-anchor">#</a> 链接到媒体</h2><p>在大多数情况下，将媒体资产插入您的内容时将使用完整的 URL。但是，也可以使用 <code>|media</code> <a href="./../markup/filter-media.html">过滤器</a> 从它们在媒体目录中的相对路径生成这些 URL。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>relative/path/to/asset.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>media <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>您还可以使用<code>MediaLibrary</code> 类在 PHP 中生成 URL。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Media<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>MediaLibrary</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;relative/path/to/asset.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="配置选项"><a href="#配置选项" class="header-anchor">#</a> 配置选项</h2><p>有几个选项允许您微调媒体管理器，这些选项在 <strong>config/media.php</strong> 文件中定义。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/*
|--------------------------------------------------------------------------
| Ignored Files and Patterns[忽略的文件和模式]
|--------------------------------------------------------------------------
|
| The media manager wil ignore file names and patterns specified here[媒体管理器将忽略此处指定的文件名和模式]
|
*/</span>

<span class="token string single-quoted-string">&#39;ignore_files&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;.svn&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;.git&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;.DS_Store&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;.AppleDouble&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>

<span class="token string single-quoted-string">&#39;ignore_patterns&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;^\\..*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>指定媒体文件保存位置的配置在系统配置文件中，请参阅有关使用第三方提供商(例如 Amazon S3)的<a href="./../media/providers.html">提供商文章</a>。</p><h4 id="svg-上传默认禁用"><a href="#svg-上传默认禁用" class="header-anchor">#</a> SVG 上传默认禁用</h4><p>出于安全原因，默认情况下在October CMS 中禁用上传 SVG 图形文件。这是因为当 SVG 文件呈现在页面上时，可能会执行恶意代码。如果您的管理区域向公众开放，我们建议您保持正常设置。</p><p>要允许在后端使用 SVG 文件，只需将其添加到图像扩展名列表中即可。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;image_extensions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;svg&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="音频和视频播放器"><a href="#音频和视频播放器" class="header-anchor">#</a> 音频和视频播放器</h2><p>默认情况下，系统使用 HTML5 音频和视频标签来渲染音频和视频文件：</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>video</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>video.mp4<span class="token punctuation">&quot;</span></span> <span class="token attr-name">controls</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>video</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>或者</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>audio</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>audio.mp3<span class="token punctuation">&quot;</span></span> <span class="token attr-name">controls</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>audio</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>此行为可以被覆盖。如果有 <strong>oc-audio-player.htm</strong> 和 <strong>oc-video-player.htm</strong> CMS 部件，它们将用于显示音频和视频内容。在部件内部使用变量 <strong>src</strong> 输出到源文件的链接。例子：</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>video</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{{ src }}<span class="token punctuation">&quot;</span></span> <span class="token attr-name">width</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>320<span class="token punctuation">&quot;</span></span> <span class="token attr-name">height</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>200<span class="token punctuation">&quot;</span></span> <span class="token attr-name">controls</span> <span class="token attr-name">preload</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>video</span><span class="token punctuation">&gt;</span></span>
</code></pre></div>`,22)),n[2]||(n[2]=a("p",null,[s("如果您不想使用 HTML5 播放器，您可以在部件中提供任何其他标记。 有一个 "),a("a",{href:"https://html5media.info/",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("第三方脚本"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),a("span",{class:"sr-only"},"(opens new window)")])]),s(" 可以在旧浏览器中支持 HTML5 视频和音频标签。")],-1)),n[3]||(n[3]=p(`<p>由于部件是用 Twig 编写的，因此您可以根据命名约定自动添加替代视频源。 例如，如果约定每个全分辨率视频总是有一个较小分辨率的视频，并且较小分辨率的文件具有扩展名<code>huawei.mp4</code>，则生成的标记可能如下所示：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>video</span> <span class="token attr-name">controls</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>source</span>
        <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> src <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">media</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>only screen and (min-device-width: 568px)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>source</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>source</span>
        <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> src<span class="token operator">|</span>replace<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string"><span class="token punctuation">&#39;</span>.mp4<span class="token punctuation">&#39;</span></span><span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>.huawei.mp4<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">media</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>only screen and (max-device-width: 568px)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>source</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>video</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="事件"><a href="#事件" class="header-anchor">#</a> 事件</h2><p>媒体管理器提供了一些 <a href="./../services/events.html">事件</a>，您可以监听它们以提高可扩展性。</p><div class="table"><table tabindex="0"><thead><tr><th>事件</th><th>说明</th><th>参数</th></tr></thead><tbody><tr><td><strong>folder.delete</strong></td><td>删除文件夹时调用</td><td><code>(string) $path</code></td></tr><tr><td><strong>file.delete</strong></td><td>删除文件时调用</td><td><code>(string) $path</code></td></tr><tr><td><strong>folder.rename</strong></td><td>重命名文件夹时调用</td><td><code>(string)$originalPath</code>,<code>(string)$newPath</code></td></tr><tr><td><strong>file.rename</strong></td><td>重命名文件时调用</td><td><code>(string)$originalPath</code>,<code>(string)$newPath</code></td></tr><tr><td><strong>folder.create</strong></td><td>创建文件夹时调用</td><td><code>(string)$newFolderPath</code></td></tr><tr><td><strong>folder.move</strong></td><td>移动文件夹时调用</td><td><code>(string) $path</code>,<code>(string)$dest</code></td></tr><tr><td><strong>file.move</strong></td><td>移动文件时调用</td><td><code>(string) $path</code>,<code>(string)$dest</code></td></tr><tr><td><strong>file.upload</strong></td><td>上传文件时调用</td><td><code>(string)$filePath</code>,<code>(\\Symfony\\Component\\HttpFoundation\\File\\UploadedFile) $uploadedFile</code></td></tr></tbody></table></div><p>要挂钩这些事件，请直接扩展<code>Media\\Widgets\\MediaManager</code> 类</p><p>\`\`php \\Media\\Widgets\\MediaManager::extend(function($widget) { $widget-&gt;bindEvent(&#39;file.rename&#39;, function ($originalPath, $newPath) { // 在此处更新对路径的自定义引用 }); });</p><div class="language- extra-class"><pre class="language-text"><code>
或者通过 \`Event\` 门面全局监听(每个事件都以 \`media.\` 为前缀，并将被实例化的 \`Media\\Widgets\\MediaManager\` 对象作为第一个参数传递)

\`\`\`php
\\Event::listen(&#39;media.file.rename&#39;, function($widget, $originalPath, $newPath) {
    // 在此处更新对路径的自定义引用
});
</code></pre></div>`,8))])}const _=l(u,[["render",d]]);export{q as __pageData,_ as default};
